import{_ as s,l as i,o as e,c as l,v as r,p as n,x as t,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"SSRF","description":"","frontmatter":{"title":"SSRF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ssrf.md","filePath":"cs/ssrf.md","lastUpdated":1789023840000}'),p={name:"cs/ssrf.md"};function E(S,a,_,f,u,m){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="ssrf" tabindex="-1">SSRF <a class="header-anchor" href="#ssrf" aria-label="Permalink to &quot;SSRF&quot;">​</a></h1><div class="epigraph"><p>服务器若把用户供给的 URL 拿去自己请求，就把防火墙后面的身份借给了输入。防御是允许名单、禁内网与重定向，而不是事后看返回体像不像 HTML。</p><footer>—— 据 OWASP SSRF；CWE-918；对照[注入](/cs/injection-boundary)</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/clickjacking">点击劫持</a>借用户手指。缺口是<strong>借服务器的网络位置</strong>。云元数据、内网管理口是典型受害者。不给打内网的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Webhook、预览、换图：应用去抓 URL。若跟重定向、改写 IP、DNS 再绑定，允许名单会被绕——只陈述要钉死解析与禁止私网段。缺口是出站策略。</p><h3 id="元数据服务" tabindex="-1">元数据服务 <a class="header-anchor" href="#元数据服务" aria-label="Permalink to &quot;元数据服务&quot;">​</a></h3><p>云实例角色凭证常在链路本地。SSRF 的危害是身份，不只是读 HTML。</p><p><span class="marginnote">CWE-918。课程禁止 SSRF 打靶教程。防御：允许名单主机、禁重定向、隔离出站。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照浏览器 CORS：那是读别人；SSRF 是服务器当客户端。下一课反序列化：输入变成对象图与代码路径。</p>',12)),(e(),n(c,null,{default:t(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20URL%5B%22%E7%94%A8%E6%88%B7%20URL%22%5D%20--%3E%20APP%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E8%AF%B7%E6%B1%82%22%5D%0A%20%20APP%20--%3E%20INET%5B%22%E5%86%85%E7%BD%91%E6%88%96%E5%85%83%E6%95%B0%E6%8D%AE%22%5D%0A%20%20APP%20--%3E%20ALLOW%5B%22%E5%85%81%E8%AE%B8%E5%90%8D%E5%8D%95%E4%B8%8E%E6%97%A0%E9%87%8D%E5%AE%9A%E5%90%91%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最小特权：应用默认不应能碰元数据与管理网。网络分段后课会再收。反序列化下一课是进程内的输入变对象。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写元数据利用步骤。反序列化下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>点击借用户；SSRF 借服务器出站。</li><li>允许名单、禁私网、慎重定向。</li><li>危害常是云身份，不只是页面。</li><li>下一课反序列化。</li><li>出处：CWE-918；OWASP SSRF。</li></ul>',8))])}const b=s(p,[["render",E]]);export{P as __pageData,b as default};
